--          Göç İdaresi Başkanlığı Genelge 2024/5 (İdari Durum Kodları Usul ve Esasları)
--          6458 Sayılı YUKK (m. 9, 13, 15, 53, 54, 56, 57/A, 102) ve EGM Hudut Talimatları
-- Toplam Kod Sayısı: 153 (Tüm Ç, V, G, N, O, Interpol ve Adli Tahdit Kodları Eksiksiz)
-- ==========================================================================================
SET NOCOUNT ON;
USE [CEZA];
GO

BEGIN TRANSACTION;
BEGIN TRY

    PRINT N'>>> TahditKod tablosu güncelleniyor ve eksik kodlar ekleniyor...';

    -- 1. Geçici Tablo Oluştur
    CREATE TABLE #FullTahditData (
        Kod NVARCHAR(MAX),
        Aciklama NVARCHAR(MAX),
        SureAy INT NULL,
        Aktif BIT,
        GirisGelirse NVARCHAR(MAX),
        CikisGelirse NVARCHAR(MAX)
    );

a)	Uluslararası koruma başvurusundan vazgeçen yabancılar hakkında, I yıl süreyle ülkeye girişi yasaklayan 0-100 kodlu veri girişi yapılır. Ancak uluslararası koruma başvuru aşamasında vize, vize muafiyeti, çalışma izni, çalışma izni muafiyeti veya ikamet izni ihlalinde olmamak koşuluyla, ikamet izni, çalışma izni ya da çalışma izni muafiyeti gibi başkaca yasal kalış hakları elde edebilmek için uluslararası koruma başvurusundan vazgeçenler İçin Başkanlık tarafından belirlenen süreler içinde 0-100 veri girişi yapılmaz.
b)	Bu genelgenin yürürlüğe girdiği tarihten önce haklarında 0-100 kodlu veri girişi yapılan yabancılara ilişkin ilgili tahdit süreleri dikkate alınır ve durumlarına uygun tahdit kodu güncellemesi yapılır.', N'MADDE 15- (I) 0-100 (Ülkeye Girişi I yıl Yasaklı Yabancı) kodlu veri girişi;
a)	Uluslararası koruma başvurusundan vazgeçen yabancılar hakkında, I yıl süreyle ülkeye girişi yasaklayan 0-100 kodlu veri girişi yapılır. Ancak uluslararası koruma başvuru aşamasında vize, vize muafiyeti, çalışma izni, çalışma izni muafiyeti veya ikamet izni ihlalinde olmamak koşuluyla, ikamet izni, çalışma izni ya da çalışma izni muafiyeti gibi başkaca yasal kalış hakları elde edebilmek için uluslararası koruma başvurusundan vazgeçenler İçin Başkanlık tarafından belirlenen süreler içinde 0-100 veri girişi yapılmaz.
b)	Bu genelgenin yürürlüğe girdiği tarihten önce haklarında 0-100 kodlu veri girişi yapılan yabancılara ilişkin ilgili tahdit süreleri dikkate alınır ve durumlarına uygun tahdit kodu güncellemesi yapılır.');
2-) Şahıs Gözaltına alınmaz ve Adli İşlem yapılmaz.
3-) Kayıp Şahıs Formu düzenlenir.
4-) Evraklarının fotokopileri alınır.
5-) Şahıs 18 yaşından küçükse Cumhuriyet Savcısının vereceği talimatlara göre işlem yapılır.
6-) Aynı gün Interpol’e bilgi verilir.', N'1-) Tahdit kaydı çıktısı alınır.
