    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-68', N'İkamet İzni Verilmesi Göç İdaresi Başkanlığı Ön İznine Tabi Yabancılar', NULL, 1, N'Vize muafiyeti veya geçerli vizesi varsa ülkeye girişine engel durum yoktur. Yabancıya Türkiye''de ikamet izni verilmesinin Başkanlık ön onayına tabi olduğu tebliğ edilir.', N'Çıkışına engel teşkil etmez, varsa vize ihlali tahsil edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-69', N'İkamet İznine İptal / Kesme / Geri Alma İşlemi Yapılan Yabancılar', 0, 1, N'İkamet izni kartı fiziken iptal edilmiştir, ikamet kartıyla giriş yapamaz. Vize muafiyeti veya geçerli konsolosluk vizesi varsa ve giriş yasağı konulmamışsa genel hükümlere göre girer.', N'Tebliğ tarihi esas alınarak ihlal hesaplanır. Tebliğ süresi içinde çıkış yapıyorsa ikamet cezası tahsil edilir; YUKK m. 27 gereği Defter Bedeli tahsil edilmez.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-70', N'Formalite (Anlaşmalı) Evlilik Yapan Yabancılar', NULL, 1, N'Aile ikamet izniyle giriş yapamaz. Hakkında Ç-kodu giriş yasağı konulmuşsa INAD edilir; yoksa normal vize rejimine göre işlem yapılır.', N'Çıkışına engel durum yoktur, ihlali varsa tahsil edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-71', N'Adres Değişikliğini Bildirmeyen / Gerçeğe Aykırı Beyan Eden Yabancılar (Semti Meçhul)', NULL, 1, N'Yabancının beyan ettiği güncel Türkiye ikamet adresi tutanağa bağlanarak POLNET ve Göç Net adres sistemine işlenir, ilgili İl Göç İdaresine bildirilir.', N'Çıkışına engel durum yoktur, ihlal varsa tahsil edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-74', N'Çıkışı Bakanlık / Valiliklere Bildirilecek Yabancılar', NULL, 1, N'Girişine engel yoktur, giriş bilgisi ilgili makama bilgi notuyla aktarılır.', N'ÖNEMLİ: Yabancının ülkeden çıkış yaptığı derhal şerhi koyan Bakanlık / Valilik birimine faks veya elektronik sistemle bildirilir. Çıkışına engel adli karar yoksa çıkışı verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-84', N'180/90 Kuralı İhlalinde 10 Gün İçinde İkamet İzni Alma Şartıyla Giriş', 0, 1, N'Yabancıya "10 Gün İçinde İkamet İzni Müracaatında Bulunacağına Dair Şartlı Giriş Tebligatı" imzalatılır ve şartlı giriş müsaadesi verilir. 10 gün içinde başvurmazsa kaçak duruma düşer.', N'10 gün içinde ikamet başvurusu yapıp yapmadığı Göç Net üzerinden sorgulanır. Başvuru yapmadan çıkan yabancıya vize ihlali cezası tahakkuk ettirilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-87', N'Gönüllü Geri Dönüş Yapan Geçici Koruma Sahibi Yabancılar (Suriyeliler)', NULL, 1, N'Geçici koruma statüsü sonlanmıştır. Göç İdaresi Başkanlığı özel izni olmaksızın tekrar giriş yapamaz, INAD uygulanır.', N'İl Göç İdaresi Gönüllü Geri Dönüş Belgesi ve yol izin belgesi kontrol edilerek çıkış tescil edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-88', N'Çalışma İzni Geçersiz Kılınan / İptal Edilen Yabancılar', 0, 1, N'İptal edilen çalışma izni kartıyla giriş yapamaz. Vizesi yoksa INAD edilir.', N'Fesih/tebliğ tarihi referans alınarak ihlal hesaplanır. YUKK m. 27 gereği İkamet Defter Bedelinden muaftır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-89', N'Geri Kabulü Sağlanan Yabancılar', NULL, 1, N'Geri kabul anlaşması kapsamında teslim alınan yabancıdır, Geri Gönderme Merkezine (GGM) sevk edilir.', N'Çıkış işlemleri GGM refakatinde yürütülür.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-91', N'Üçüncü Ülkeye Çıkışı Bakanlık/Valiliklere Bildirilecek Yabancılar', NULL, 1, N'Giriş yaptığında şerh koyan makama bilgi verilir.', N'Çıkış yaptığı anda şerhi koyan makama sistem üzerinden derhal bildirim yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-92', N'Mükerrer Kaydı Olan Geçici Koruma Sahibi Yabancılar', NULL, 1, N'Mükerrer kayıt tespiti için parmak izi doğrulaması yapılır, İl Göç İdaresine yönlendirilir.', N'Gerçek kimlik ve mükerrer kayıt kontrolü yapılarak çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-137', N'Türkiye''yi Terke Davet Edilen Yabancılar (YUKK Madde 54)', 0, 1, N'Terke davet kararı yürürlükteyken giriş verilmez. Ç-kodu girişi varsa INAD edilir.', N'KRİTİK UYGULAMA: Tebliğ edilen terke davet süresi içinde (10-30 gün) çıkış yapıyorsa giriş yasağı ve para cezası uygulanmaz. Terke davet süresini aşarak çıkanlara 20.605 TL İdari Para Cezası tahakkuk ettirilir ve ihlal süresine göre tahdit kodu işlenir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-144', N'57-A Kapsamında İdari Gözetimi Sonlandırılarak Serbest Bırakılanlar', NULL, 1, N'Girişine izin verilmez, GGM veya ilgili kolluk birimine bilgi verilir.', N'İdari gözetim sonlandırma kararı ve yol belgesi kontrol edilir, çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-145', N'Gönüllü Geri Dönüş Programı ile Çıkış Yapanlar', NULL, 1, N'Gönüllü geri dönüş formu sorgulanır; giriş yasağı varsa giriş verilmez.', N'Gönüllü geri dönüş evrakı kontrol edilerek çıkışı tescil edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-146', N'Türk Pasaportu Şerhli Şahıslar', NULL, 1, N'Türk vatandaşının ülkesine giriş hakkı engellenemez, girişi sağlanarak ilgili birime bilgi verilir.', N'Pasaportun geçerliliği ve zayi/tahdit durumu POLNET üzerinden sorgulanır; pasaport iptal ise çıkış verilmez, pasaporta el konulur.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-147', N'Pasaportu Şerhli Türk Vatandaşı Eşi', NULL, 1, N'Şerh mahiyeti tahkik edilir, ilgili makama bildirilir.', N'Çıkış tahdidi varsa çıkış verilmez, yoksa işlem tamamlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-148', N'Geçici Barınma Merkezinde Barınan Yabancılar', NULL, 1, N'Geçici barınma merkezi kayıtları incelenir, yol izin belgesi sorgulanır.', N'Yol izin belgesi kontrol edilerek çıkışı tescil edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-153', N'AYM Kendi Ülkesine ve Üçüncü Ülkeye İlişkin Tedbir Kararı (YUKK m. 53, AYM Tedbir)', NULL, 1, N'Genel vize ve pasaport mevzuatına göre işlem yapılır; tek başına ülkeye girişe engel durum bildirir kod değildir.', N'Anayasa Mahkemesi tedbir kararı gereğince yabancının kendi ülkesine veya üçüncü bir ülkeye sınır dışı ve çıkışı DURDURULUR. Başkanlık veya mahkeme talimatı olmadan çıkışına izin verilmez.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-154', N'Sınır Dışı Etme Kararına Karşı İdare Mahkemesine Başvuranlar', NULL, 1, N'Dava sonucu ve yürütmeyi durdurma kararı kontrol edilir.', N'Kendi rızasıyla çıkıyorsa dava hakkından feragat etmiş sayılır, çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-155', N'Avrupa İnsan Hakları Mahkemesi (AİHM) Tedbir Kararı (AİHM İçtüzük 39. Madde)', NULL, 1, N'Genel hükümlere göre işlem yapılır; tek başına ülkeye girişe engel değildir.', N'AİHM kural 39 tedbir kararı uyarınca sınır dışı ve çıkış işlemleri DURDURULUR. Başkanlık yazılı talimatı beklenir, resen çıkış işlemi yapılamaz.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-156', N'Avukatlık Vekâlet Ücreti ve Yargılama Gideri Borcu (Göç İdaresi Başkanlığı Hukuk Müşavirliği)', NULL, 1, N'Yabancıya Göç İdaresi Başkanlığı Merkez Bankası emanet hesabına mahkeme vekalet ücreti borcunu ödemesi gerektiği tebliğ edilir; girişe engel teşkil etmez, genel hükümlere göre girişi sağlanır.', N'Çıkışına engel değildir. Borç bilgileri tebliğ edilir, tahsilat makbuzu kontrol edilerek veya borç kaydı bildirilerek çıkışına izin verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-157', N'İkamet İzni Talepleri Reddedilen Yabancılar', NULL, 1, N'Reddedilen başvuruyla giriş yapamaz. Vize rejimi şartlarını sağlamıyorsa INAD edilir.', N'Tebliğ tarihinden itibaren tebliğ edilen süre içinde çıkıyorsa normal işlem; süreyi aşmışsa aştığı gün kadar ihlal harcı tahsil edilir. Defter bedeli alınmaz.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-158', N'Yabancı Temsilcilik Personeli / Aile Bireyi Kimlik Kartı İptal Edilenler', NULL, 1, N'Diplomatik/konsolosluk kartı iptal edilmiştir, bu kartla giremez.', N'Çıkışına engel durum yoksa çıkışı yapılır, Dışişleri Bakanlığına bilgi verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-159', N'Başkanlıkça Ülkemizden Sadece Transit Geçişine İzin Verilen Yabancılar', NULL, 1, N'Yalnızca transit geçişine izin verilir, belirlenen sürede ülkeyi terk etmek zorundadır.', N'Transit süresi içinde çıkıp çıkmadığı kontrol edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-160', N'Semti Meçhule Giden Yabancılar (İkamet Adresinde Bulunmayanlar)', NULL, 1, N'Güncel ikamet adresi tutanağa bağlanır, İl Göç İdaresine bildirilir.', N'Varsa ihlal cezası tahsil edilir, çıkışı yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-161', N'AYM Kendi Ülkesine Tedbir Kararı (YUKK m. 53, 55 Menşe Ülkeye İade Yasağı)', NULL, 1, N'Girişe engel teşkil etmez; genel vize/pasaport rejimine göre işlem tesis edilir.', N'Yabancının SADECE kendi menşe ülkesine sınır dışı ve çıkışı DURDURULUR. Başka bir üçüncü ülkeye geçerli vize veya biletle seyahat etmek istemesi halinde çıkışına izin verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-162', N'Mahkemece / Sulh Ceza Hakimliğince İdari Gözetimi Sonlandırılan Yabancılar (YUKK m. 57/6)', NULL, 1, N'Genel hükümlere göre işlem yapılır; girişe engel idari durum kodu değildir.', N'Yabancı kendiliğinden sınır kapısına geldiğinde sınır kapısı personeli tarafından V-162 kodu kaldırılır ve varsa durumuna uygun diğer tahdit kodları (para cezası/harç) girilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-163', N'Detaylı İncelemeye Tabi Tutulacak Yabancılar (Düzensiz Göç Risk Analiz Birimi Mülakatı)', NULL, 1, N'Yolcu derhal Düzensiz Göç Risk Analiz Birimi''ne yönlendirilir. Birimce girişi uygun görülürse sınır personeli V-163 kodunu kaldırıp girişi sağlar; uygun görülmezse İNAD işlemi uygulanarak geri gönderilir.', N'Çıkışına mani bir durum yoktur; genel vize ve pasaport kontrolleri yapılarak çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-164', N'Sınır Dışı Etme İşlemi Gerçekleştirilen Yabancılar (Kolluk Refakatinde Sınır Dışı)', NULL, 1, N'Sınır dışı edilen şahıstır; hakkında aktif giriş yasağı (Ç veya G kodu) bulunur, ülkeye girişine izin verilmez ve İNAD işlemi uygulanır.', N'Kolluk refakatinde sınır kapısına getirilir; refakatçi personelin sınır dışı teslim-tesellüm tutanağı kontrol edilerek çıkışı tamamlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-165', N'Geçici Koruma Kayıt İşleminde Sahtecilik / 4 ve Üzeri Yalan Beyanda Bulunan Yabancılar', NULL, 1, N'Mükerrer sahte kayıt nedeniyle ülkeye girişine izin verilmez. Yetkili makamın yazılı talimatı ve tahkikatı beklenir.', N'Yabancının varsa idari para cezaları tahsil edilir; ödemeyenler hakkında N-120 ve ilgili giriş yasağı tahdidi girilerek çıkışı yaptırılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-173', N'Geçici Giriş İzni Verilen Suriyeli Yabancılar (Geçici Koruma Kapsamı Dışı İzin)', NULL, 1, N'Başkanlık veya Valilik geçici giriş izin belgesi kontrol edilir, V-173 kodu işlenerek izin süresince girişine izin verilir (geçici koruma verilmez).', N'Sınır kapısına geldiğinde sınır kapısı personeli tarafından V-173 kodu kaldırılarak çıkışı sağlanır. Süreyi aşmışsa V-216 ve idari para cezası tahakkuk ettirilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-174', N'Tedavi Amaçlı Giriş İzni Verilen Suriyeli Yabancılar (Sağlık Bakanlığı / Ambulans Sevki)', NULL, 1, N'Sağlık Bakanlığı hastane sevk belgesi ve ambulans kontrolüyle sınır kapısı personeli tarafından V-174 kodu girilerek girişine izin verilir.', N'Tedavisi tamamlanıp çıkışa geldiğinde sınır personeli tarafından V-174 kodu kaldırılarak çıkışı sağlanır. Tedavi süresini haklı mazeretsiz aşmışsa idari para cezası tahakkuk ettirilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-175', N'Geçici Koruma Sonlandırılmaksızın Suriye''ye İzinli Giriş-Çıkış Yapan Yabancılar', NULL, 1, N'Tanınan izin süresi içinde dönmüşse sınır kapısı personeli tarafından V-175 kodu kaldırılarak ülkeye girişi sağlanır. Süresinde dönmemişse idari para cezası ve ön izin hükümleri uygulanır.', N'Valilik/Başkanlık izin belgesi kontrol edilerek sınır personeli tarafından V-175 kodu girilir ve Suriye''ye çıkışı yaptırılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-177', N'Sınır Dışı Kararı Olan ve Menşe Ülkesine Çıkışı Sağlanan Suriyeli Yabancılar', NULL, 1, N'Hakkında sınır dışı kararı ve giriş yasağı bulunan şahıstır; ülkeye girişine izin verilmez, İNAD işlemi uygulanır.', N'İl Göç İdaresi refakatinde çıkışı sağlanır; sisteme V-177 ve V-145 kodları girilerek çıkış işlemi tamamlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-178', N'57/A Kapsamında İşlemleri Devam Ederken Ülkemizden Çıkışı Sağlanan Yabancılar', NULL, 1, N'Genel vize ve tahdit hükümleri uygulanır; aktif giriş yasağı varsa İNAD işlemi yapılır.', N'İdari gözetime alternatif yükümlülük altındayken çıkışa gelen yabancı hakkında sınır personeli tarafından V-178 ve V-145 kodlu veri girişi yapılarak çıkışına izin verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-179', N'Ulusal Destekli Gönüllü Geri Dönüş Mekanizması Kapsamında Ülkemizden Çıkışı Sağlanan Yabancı', NULL, 1, N'Genel hükümlere ve varsa giriş yasağı/ön izin şartına göre değerlendirilir.', N'İl Göç İdaresi koordinasyonunda V-179 ve V-145 kodları işlenerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-180', N'AVRR (Uluslararası Kuruluşlar) Programları Kapsamında Çıkışı Sağlanan Yabancı', NULL, 1, N'Genel vize ve pasaport hükümleri uygulanır; varsa tahdit kontrolleri yapılır.', N'IOM / AVRR programı kapsamında V-180 ve V-145 kodlu veri girişi yapılarak çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-181', N'Ülkemize İllegal Girip Çıkış Yapmak Üzere Kendiliğinden Gelen Yabancılar (YUKK m. 5)', NULL, 1, N'Yasadışı giriş nedeniyle hakkında Ç-113 (5 yıl yasak) ve N-135 borç kodu uygulanır, girişine izin verilmez.', N'Hudut kapısına kendiliğinden çıkışa geldiğinde V-181 (Suriyeli değilse ayrıca V-145) girilir, Ç-113 (5 yıl yasak) ve yasadışı giriş para cezası tahakkuk ettirilerek çıkışı yaptırılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-182', N'Terke Davet Edilip Süresinde / Süresi Dışında Ülkemizden Çıkış Yapanlar (YUKK m. 56)', NULL, 1, N'Genel vize rejimine göre değerlendirilir; yasaklı süresi yoksa ve borcu yoksa girişi sağlanır.', N'Sınır kapısına geldiğinde sınır kapısı personeli tarafından V-182 kodu girilir ve önceki V-137 kodu kaldırılır; para cezası ve giriş yasağı kontrolü yapılarak çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-183', N'O Kaydı Olup Ülkemizden Çıkış Yapan Yabancılar (Uluslararası Koruma Vazgeçme/Sonlanma)', NULL, 1, N'O-100, O-176 veya O-177 kodundaki giriş yasağı süresi dolmadan girişine izin verilmez, İNAD uygulanır.', N'Çıkışında sınır personeli tarafından V-183 ve V-145 kodlu veri girişi yapılır; uluslararası koruma sonlandırma prosedürüyle çıkışı yaptırılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-188', N'Kabul Edilemeyen Yolcu (İNAD) Olmasına Rağmen Başkanlık / Kamu Kurumu Talebiyle Girişine İzin Verilenler', NULL, 1, N'Başkanlık uygun görüşü veya Kamu Kurumu talebiyle sınır kapısı personeli tarafından açıklamasına ''Kamu Kurumu Talebi'' yazılarak V-188 girilir ve girişi sağlanır. Valilik başvurularına engel teşkil etmez.', N'Yabancı çıkış yapmak üzere hudut kapısına geldiğinde sınır kapısı personeli tarafından V-188 kodu kaldırılarak çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-189', N'Sınır Vizesi Düzenlenerek Ülkemize Girişine İzin Verilen Yabancılar (6458 Sayılı Kanun m. 13)', NULL, 1, N'YUKK 13. madde kapsamında sınırda vize vermeye yetkili makamca sınır vizesi düzenlenerek V-189 girilir ve ülkeye girişi sağlanır.', N'Çıkış yapmak üzere sınır kapısına geldiğinde sınır kapısı personeli tarafından V-189 kodu kaldırılarak genel hükümlere göre çıkışı yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-190', N'Üçüncü Ülke Tarafından Sınır Dışı Edilmiş Yabancılar (Transit / İade)', NULL, 1, N'Ülkeye girişleri genel hükümlere tabi olmakla birlikte Kanun kapsamındaki başvurularında detaylı incelenir. Başkanlık talimatı olmadan kod kaldırılmaz.', N'Çıkışına engel durum yoktur; genel vize/pasaport kurallarına göre çıkışı yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-191', N'Mahkemelerce Hakkında Kişisel Bilgilerine Dair Gizlilik Kararı Verilen Yabancılar', NULL, 1, N'Yolcunun kimlik ve seyahat bilgileri gizlilik kararı çerçevesinde korunur; sistem kayıtları yetkisiz kişilerle paylaşılmaz, genel hükümlere göre girişi sağlanır.', N'Kişisel verilerin gizliliği ilkesine titizlikle uyularak çıkış işlemi gerçekleştirilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-192', N'İkamet İzni Başvurusu Değerlendirme Aşamasında Olan Yabancılar (İkamet İzni Müracaat Belgesi)', NULL, 1, N'Geçerli İkamet İzni Müracaat Belgesi ve harç makbuzu kontrol edilir; 90 güne kadar yurt dışında kalmışsa genel hükümlere göre girişi sağlanır.', N'İkamet izni müracaat belgesi hamillerinin 15 güne kadar yurt dışına çıkış hakkı mevcuttur; genel hükümlere göre çıkışına izin verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-193', N'İdari Gözetime Alternatif Yükümlülük (İGA) 24 Ay Sonrasında İnsani İkamet İzni Hamili Yabancılar', NULL, 1, N'İnsani ikamet izni geçerli olduğu sürece girişine izin verilir.', N'Çıkış yapmak üzere sınır kapısına geldiğinde çıkışına izin verilir ve durum resmi yazı ile insani ikamet iznini düzenleyen İl Göç İdaresi Müdürlüğüne ivedilikle bildirilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-194', N'İGA 24 Aylık Süre Sonrasında Geçici Koruma Kapsamına Alınan Yabancılar', NULL, 1, N'Geçici koruma genel mevzuatına göre işlem tesis edilir.', N'Geçerli yol izin belgesi veya çıkış izni kontrol edilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-195', N'İGA 24 Aylık Süre Sonrasında Uluslararası Koruma Kapsamına Alınan Yabancılar', NULL, 1, N'Uluslararası koruma statüsü ve kimlik belgesi kontrolüyle giriş sağlanır.', N'İl Göç İdaresi çıkış izni ve seyahat belgesi kontrol edilerek çıkışı yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-196', N'Menfi Uluslararası Koruma Kararına Karşı İdare Mahkemesine ya da İtiraz Komisyonuna Başvuranlar (YUKK m. 80)', NULL, 1, N'Girişe engel durum bildirir kod değildir.', N'Yargılama ve komisyon süreci devam ederken sınır dışı işlemi durdurulur; kendiliğinden çıkış yapmak isterse İl Göç İdaresine bilgi verilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-197', N'Uluslararası Koruma Kapsamında Haksız Yere Hak ve Hizmetlerden Yararlanan Yabancı (Kamu Zararı Borcu)', NULL, 1, N'Kamu zararı alacağı uyarısı verilir; girişe engel değildir, genel vize hükümlerine göre girişi sağlanır.', N'Kamu zararı geri ödeme takibi için İl Göç İdaresine bilgi verilir; çıkış engeli oluşturmaz.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-198', N'İkamet İli Dışında Yol İzin Belgesiz İzinsiz Yakalanan Geçici Koruma Kapsamındaki Yabancı', NULL, 1, N'Giriş kapılarında uygulanmaz.', N'İdari para cezası tahakkuku kontrol edilir ve yabancı kayıtlı bulunduğu ile yönlendirilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-199', N'Yeniden Yerleştirme Programı Kapsamına Alınan Yabancı (Üçüncü Ülkeye Yerleştirme)', NULL, 1, N'Başkanlık özel izni aranır.', N'Başkanlık ve UNHCR yeniden yerleştirme belgeleri kontrol edilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-200', N'Yeniden Yerleştirme Kapsamında Üçüncü Ülkeye Yerleştirilen Yabancı (Türkiye Statüsü Sona Eren)', NULL, 1, N'Üçüncü bir ülkeye yerleştirildiğinden Türkiye''deki geçici/uluslararası koruması sonlandırılmıştır; genel vize/pasaport rejimine tabidir.', N'Çıkış işlemi tamamlandıktan sonra V-199 kaldırılarak V-200 kodu işlenir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-201', N'Geri Gönderme Merkezinde Özel İhtiyaç Sahibi Olması Sebebiyle İGA''ya Tabi Tutulan Yabancı', NULL, 1, N'Genel hükümlere göre işlem yapılır.', N'Alternatif yükümlülük takibi yapılır; çıkış halinde ilgili İl Göç İdaresine bilgi verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-202', N'Refakatsiz Çocuk Olduğu Tespit Edilerek Aile ve Sosyal Hizmetler Bakanlığına (ASHB) Yönlendirilen Yabancı', NULL, 1, N'Yetkili vasi veya ASHB görevlisi refakati olmaksızın çocuğun tek başına girişine izin verilmez.', N'Yetkili mahkeme kararı ve ASHB onayı olmadan refakatsiz çocuğun ülkeden çıkışına kesinlikle izin verilmez!');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-203', N'Çıkışı Sonrası O-100 (1 Yıl Giriş Yasağı) Girilecek Yabancı (UK Başvurusundan Vazgeçen)', NULL, 1, N'Giriş kapısında uygulanmaz.', N'Yabancının ülkemizden çıkışı yapıldıktan sonra sınır kapısı personeli tarafından V-203 kodu kaldırılır ve derhal O-100 kodlu (1 yıl süreli giriş yasağı) veri girişi yapılır!');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-204', N'Çıkışı Sonrası O-176 (3 Yıl Giriş Yasağı) Girilecek Yabancı (UK Başvurusu Geri Çekilmiş/Sona Eren)', NULL, 1, N'Giriş kapısında uygulanmaz.', N'Yabancının çıkışı yapıldıktan sonra sınır kapısı personeli tarafından V-204 kodu kaldırılır ve derhal O-176 kodlu (3 yıl süreli giriş yasağı) veri girişi yapılır!');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-205', N'Çıkışı Sonrası O-177 (5 Yıl Giriş Yasağı) Girilecek Yabancı (UK Başvurusu Reddedilen/İptal Edilen)', NULL, 1, N'Giriş kapısında uygulanmaz.', N'Yabancının çıkışı gerçekleştikten sonra sınır kapısı personeli tarafından V-205 kodu kaldırılır ve derhal O-177 kodlu (5 yıl süreli giriş yasağı) veri girişi yapılır!');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-209', N'Çıkışı Başkanlık Onayına Tabi Yabancılar (Yeniden Yerleştirme Öncesi Özel Değerlendirme)', NULL, 1, N'Girişe engel teşkil etmez.', N'Göç İdaresi Başkanlığı''nın resmi yazılı izni ve onayı olmadan KESİNLİKLE ülkeden çıkışına izin verilmez!');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-210', N'Havalimanı Göç İdaresi Birimi Tarafından İşlem Yapılan Yabancı (Tahditsiz Yasal Kalış İhlali)', NULL, 1, N'Havalimanına gelen yabancının V-210 kodu sınır kapısı personeli tarafından kaldırılarak vize umumi hükümleri çerçevesinde girişi sağlanır.', N'Çıkışına engel durum yoktur; ihlal ve harç kontrolleri yapılarak çıkışına izin verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-211', N'Parmak İzi Biyometrik Kaydı Bulunmayan Yabancı (Sistem Tarafından Otomatik Tanzim Edilen Kod)', NULL, 1, N'Sınır kapısına geldiğinde derhal biyometrik parmak izi veri alım birimine yönlendirilir; parmak izi verisi alındıktan sonra V-211 kodu kaldırılarak girişi sağlanır.', N'Parmak izi verisi eksikse sınır parmak izi biriminde verisi tamamlatılarak çıkışına izin verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-212', N'Uluslararası Koruma: Çalışma İzni Bitiminde Kayıtlı Olduğu İkamet İline Dönecek Yabancı', NULL, 1, N'Genel UK rejimine tabidir.', N'Eski ikamet iline intikal durumu ve çalışma izni iptal/bitim takibi yapılır; çıkışına mani adli tahdit yoksa çıkışı yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-213', N'Uluslararası Koruma: Öğrenim Süreci Bitiminde İkamet İline Dönecek Yabancı', NULL, 1, N'Genel UK rejimine tabidir.', N'Öğrenim durumunun sonlanması ve ikamet ili koordinasyonu kontrol edilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-214', N'Uluslararası Koruma: Sağlık Gerekçesi Sonlanıp İkamet İline Dönecek Yabancı', NULL, 1, N'Genel UK rejimine tabidir.', N'Sağlık sebebiyle sevk takibi yapılır; çıkışında engel yoktur.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-215', N'Bildirim Yükümlülüğü Getirilen Geçici Koruma Sahibi Yabancı (İmza / Adres Doğrulama)', NULL, 1, N'Genel GK mevzuatına göre işlem görür.', N'Bildirim yükümlülüğünü ihlal edip etmediği ve yol izin belgesi kontrol edilerek çıkış işlemi yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-216', N'Geçici Giriş/Çıkış İzni Verilenlerden Süresinde Dönmeyen / Semti Meçhule Giden Suriyeliler', NULL, 1, N'Süresi içinde dönmediğinden ve kurallara uymadığından ülkeye girişine izin verilmez, İNAD uygulanır.', N'Sınır kapısı personeli tarafından V-216 kodu kaldırılarak ilgili idari para cezaları ve ön izin tahakkuku yapılarak çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-217', N'Kamu Düzeni / Kamu Güvenliği / Kamu Sağlığı Sebebiyle Geçici Koruması İptal Edilen Yabancılar (GKY m. 8)', NULL, 1, N'Kamu düzeni/güvenliği gerekçesiyle ülkeye girişine KESİNLİKLE izin verilmez, derhal İNAD (Kabul Edilemeyen Yolcu) işlemi uygulanır.', N'Sınır dışı etme kararına istinaden kolluk refakatinde çıkışı yaptırılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-218', N'Sınır Dışı Seyahat Masrafı Vize Sigortasından Karşılanacak Yabancı', NULL, 1, N'Girişte uygulanmaz.', N'Sınır dışı seyahat bilet ve intikal masrafları vize sigortası poliçesinden mahsup edilmek üzere gerekli tutanak ve belgeler düzenlenerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-219', N'Geçici Koruma Yönetmeliği 8. Maddesi 3. Fıkrası Kapsamındaki Yabancı', NULL, 1, N'Başkanlık ve ilgili mevzuat hükümlerine göre izin verilir.', N'İl Göç İdaresi ve kolluk tahkikatı doğrultusunda çıkış işlemi tesis edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-220', N'Olağanüstü Gelişmeler / İnsani Nedenlerle Türkiye''ye Girişine İzin Verilen Yabancılar', NULL, 1, N'Ülkesinde yaşanan savaş/olağanüstü haller sebebiyle sınır kapılarından V-220 girilerek geçici kabulü sağlanır; yasal statü alsa bile kod kaldırılmaz.', N'Yabancı ülkemizden ayrılmak üzere sınır kapısına geldiğinde sınır kapısı personeli tarafından V-220 kodu kaldırılarak genel hükümlere göre çıkışı yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-221', N'İnterpol - Terör Suçları Kapsamında Kapsamlı Kontrole Tabi Yabancılar', NULL, 1, N'Derhal İnterpol-Europol Daire Başkanlığı ve TEM Şube Müdürlüğüne bilgi verilir. Yapılan kapsamlı kontrol sonucu sakınca görülmezse sınır personeli V-221''i kaldırıp girişi sağlar; sakınca görülürse İNAD işlemi uygulanır.', N'İnterpol ve TEM birimlerine ivedilikle bilgi verilir; adli arama/yakalama kararı yoksa kontrollü çıkışı sağlanır, varsa yakalama prosedürü işletilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-222', N'İnterpol - Terör Harici Diğer Suçlar Kapsamında Kapsamlı Kontrole Tabi Yabancılar', NULL, 1, N'İnterpol-Europol Dairesine bilgi verilir; detaylı adli kontrole tabi tutulur. Sakınca görülmezse sınır personeli V-222 kodunu kaldırıp girişi sağlar; aksi halde İNAD işlemi uygulanır.', N'İnterpol bülten kaydı ve uluslararası aranma durumu teyit edilir; adli yakalama yoksa çıkışına izin verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-223', N'Davet Yükümlülüğüne Uymayan Yabancı (6458 Sayılı Kanun m. 97)', NULL, 1, N'Genel vize ve pasaport mevzuatına göre işlem yapılır.', N'Yabancı kendiliğinden sınır kapısından çıkmak üzere geldiğinde sınır kapısı personeli tarafından V-223 kodu kaldırılarak çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-101', N'Vize, vize muafiyeti, ikamet veya çalışma iznini 3 aya kadar ihlal edip ceza ödemeden çıkanlar veya 3-6 ay ihlal edip ceza ödeyenler (Genelge 2024/5 m. 6)', 3, 1, N'Tahdit süresi (3 ay) dolmadan kesinlikle yurda giriş verilemez. Giriş kapısına geldiğinde Kabul Edilemeyen Yolcu (INAD) tebligatı yapılır ve ilk vasıtayla geldiği ülkeye iade edilir. Süre bittikten sonra gelişinde ödenmemiş para cezası borcu (N-120) kontrol edilir; ceza vezneye tahsil ettirilmeden ve vize şartı sağlanmadan giriş yaptırılmaz.', N'Yabancının Türkiye''ye yasal giriş yapıp yapmadığı kontrol edilir. Yeni bir vize ihlali varsa hesaplanıp tahsil edilir. Hakkında adli çıkış yasağı yoksa çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-102', N'Yasal kalış süresini 6 ay ila 1 yıl arasında ihlal edip cezasını ödeyenler veya 3-6 ay ihlal edip cezasını ödemeden çıkan yabancılar (Genelge 2024/5 m. 6)', 6, 1, N'6 aylık yasak süresi bitene kadar yurda giriş verilemez. Doğrudan Kabul Edilemeyen Yolcu (INAD) kapsamına alınarak mahrecine geri çevrilir. Süre dolduktan sonra ödenmemiş para cezası tahsil edilmeden girişine izin verilmez.', N'Çıkış kapısında kaçak giriş/çıkış kontrolü yapılır, varsa yeni ihlal hesaplanır ve tahsil edilir. Adli bir arama kaydı yoksa çıkışı verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-103', N'Yasal kalış süresini 1 yıl ila 2 yıl arasında ihlal edip cezasını ödeyenler veya 6 ay ila 1 yıl ihlal edip cezasını ödemeden çıkan yabancılar (Genelge 2024/5)', 12, 1, N'1 yıl (12 ay) süreyle Türkiye''ye girişi yasaktır. Hudut kapısında kabul edilmeyen yolcu işlemi (INAD) uygulanarak sınır dışı edilir. Süre bitiminde borç tahsilatı ve vize şartı aranır.', N'Çıkışına engel adli mahkeme kararı (CMK 109) yoksa, varsa güncel ihlal cezaları tahsil edilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-104', N'Yasal kalış süresini 2 yıl ila 3 yıl arasında ihlal edip cezasını ödeyenler veya 1 yıl ila 2 yıl ihlal edip cezasını ödemeden çıkan yabancılar (Genelge 2024/5)', 24, 1, N'2 yıl süreyle yurda girişi yasaktır. Kapıda INAD tebliği yapılarak havayolu/taşıyıcı şirket aracılığıyla mahrecine iade edilir.', N'Giriş mühürleri ve pasaport kontrol edilir, yeni ihlal varsa tahsil edilir ve çıkışı tamamlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-105', N'Yasal kalış süresini 3 yıldan fazla ihlal edip cezasını ödeyenler veya 2 yıldan fazla ihlal edip cezasını ödemeden çıkan yabancılar (Genelge 2024/5)', 60, 1, N'5 yıl süreyle ülkeye girişine izin verilmez. INAD prosedürü uygulanarak derhal geri çevrilir. İstizanlı vize veya mahkeme kararı olmadan giriş verilemez.', N'Çıkış kapısında mevcut ihlal cezaları tahsil edilir, ödemezse N-120 tahdidi konulacağı tebliğ edilerek çıkışı verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-113', N'Yasadışı Giriş-Çıkış Yapan veya Teşebbüs Eden Yabancılar (Genelge 2024/4 Madde 8)', 60, 1, N'5 yıl süre ile yurda girişi yasaktır. Giriş kapısına geldiğinde doğrudan INAD (Kabul Edilemez Yolcu) kapsamına alınarak geldiği ülkeye geri gönderilir.', N'Yasadışı yollardan giriş yapıp yapmadığı, sahte mühür/belge olup olmadığı incelenir. Sahtecilik varsa derhal adli tahkikat başlatılır (TCK 204), Nöbetçi Savcılığa bilgi verilir. Adli işlem sonrası sınır dışı kapsamında kontrollü çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-114', N'Hakkında Adli İşlem Yapılan Yabancılar / Para Cezasını Ödemeden Çıkanlar (Genelge 2024/4 m. 9 ve Genelge 2024/5 m. 6)', 36, 1, N'3 yıl boyunca Türkiye''ye girişi yasaktır. Ödenmemiş idari para cezası tahsil edilmeden ve süre dolmadan giriş verilmez. İstizanlı meşruhatlı vizesi yoksa INAD işlemi uygulanarak geri çevrilir.', N'UYAP/POLNET üzerinden adli makamlarca konulmuş bir yurt dışına çıkış yasağı (CMK 109/3-a) olup olmadığı kontrol edilir. Çıkış yasağı yoksa, ihlal para cezası tahakkuk ettirilerek tahsilatı yapılır; ödemezse N-120 şerhi işlenerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-115', N'Cezaevinden Tahliye Olan Yabancılar (Genelge 2024/4 Madde 10)', 60, 1, N'5 yıl boyunca ülkeye girişi yasaktır. Hudut kapısına geldiğinde derhal INAD işlemi uygulanarak geldiği ülkeye iade edilir.', N'Cezaevi tahliye belgesi ve Geri Gönderme Merkezi (GGM) sınır dışı/terke davet kararı kontrol edilir. Güvenlik birimleri nezaretinde çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-116', N'Geçimini Meşru Olmayan Yollardan Sağlayan Yabancılar (Genelge 2024/4 Madde 11)', 60, 1, N'5 yıl süreyle ülkeye girişi yasaktır. Pasaport kontrolünde INAD tebligatı yapılarak geldiği ülkeye geri çevrilir.', N'Çıkışına mani adli bir yakalama veya mahkeme tedbiri yoksa çıkış işlemi tamamlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-117', N'Çalışma İzni Olmadan Çalıştığı Tespit Edilen Yabancılar (Genelge 2024/4 Madde 12)', 12, 1, N'1 yıl süreyle giriş izni verilmez. Hudut kapısında INAD işlemi uygulanarak geri gönderilir.', N'Kaçak çalışma idari para cezası ve vize ihlal cezaları tahsil edilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-118', N'Kamu Sağlığını Tehdit Eden Bulaşıcı Hastalık Taşıyan Yabancılar (6458 Sayılı Kanun m. 15/1-b)', 60, 1, N'Ülkeye girişi yasaktır. Hudut Sağlık Denetleme Merkezi görevlileri nezaretinde koruyucu sağlık tedbirleri alınarak derhal INAD kapsamında geri çevrilir.', N'Sağlık birimleri koordinesinde güvenli çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-141', N'Uluslararası Güvenlik Açısından Sakıncalı Görülen Yabancılar (Genelge 2024/4 Madde 14 - Bakanlık İzni)', 60, 1, N'KESİNLİKLE YURDA GİRİŞ VERİLEMEZ. İçişleri Bakanlığı / Göç İdaresi Başkanlığı özel yazılı izni olmaksızın vizesi olsa dahi giriş yaptırılmaz. Derhal Terörle Mücadele (TEM) ve İstihbarat Şube Müdürlüğü nöbetçi amirine bilgi verilerek INAD işlemi uygulanır.', N'Hakkında adli arama kaydı, yakalama müzekkeresi olup olmadığı kontrol edilir; TEM/İstihbarat Şube bilgilendirilerek alınacak talimat doğrultusunda işlem yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-149', N'Ülkeden Çıkışı Sağlanan Yabancı Terörist Savaşçı (YTS)', 60, 1, N'Kesinlikle ülkeye sokulmaz. TEM Şube görevlileri gözetiminde derhal INAD kapsamına alınarak geldiği ülkeye iade edilir.', N'Kolluk/GGM refakatinde çıkış işlemi yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-150', N'Sahte Belge ile Giriş-Çıkış Yapmak İsteyen Yabancılar (5 Yıl Giriş Yasağı)', 60, 1, N'Sahte belgeye el konularak muhafaza altına alınır. Nöbetçi Cumhuriyet Savcısına bilgi verilerek adli işlem başlatılır (TCK 204/207). Adli işlemler sonrasında INAD edilir.', N'Sahte belge ile çıkış teşebbüsü suçüstü adli işlem gerektirir. Şahıs gözaltına alınarak adli tahkikat için ilgili kolluk birimine teslim edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-151', N'Göçmen Kaçakçılığı Suçuna Karışan Yabancılar (TCK m. 79)', 60, 1, N'Ülkeye giriş verilmez. Göçmen Kaçakçılığıyla Mücadele (GÖKSEM) ve adli mercilere bilgi verilerek INAD işlemi yapılır.', N'Adli kontrol kararı ve yakalama emri kontrol edilir, engel yoksa çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-152', N'Ülkeye Girişi İhtiyaten Engellenen Yabancılar (1 Yıl Süreli)', 12, 1, N'İhtiyati yasak süresince giriş verilmez, INAD uygulanır.', N'Çıkışına engel teşkil etmez.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-166', N'Girişini Haklı Nedene Dayandırmayan / Maddi İmkânı Bulunmayan (YUKK m. 15)', 12, 1, N'Kabul Edilmeyen Yolcu işlemi yapılarak geri çevrilir.', N'Çıkış işlemi normal tamamlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-179', N'Organ ve Doku Ticareti Suçuna Karışanlar (5 Yıl Yasak)', 60, 1, N'Girişi kesinlikle yasaktır, INAD işlemi yapılır ve KOM Şube bilgilendirilir.', N'Adli yakalama kararı sorgulanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-184', N'Kamu Güvenliği Sebebiyle Kabul Edilemeyen Yolcu (5 Yıl Yasak)', 60, 1, N'Derhal INAD işlemi uygulanarak geri çevrilir.', N'Güvenlik kontrolünden sonra çıkışı verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-185', N'İnsan Ticareti Suçuna Karışan Yabancılar (5 Yıl Yasak)', 60, 1, N'Girişi yasaktır, derhal GÖKSEM ve adli makamlara bilgi verilir, INAD uygulanır.', N'Adli yakalama emri sorgulanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-95', N'Giriş Yasağı İhlalinin İdari Para Cezası Tahdidi', NULL, 1, N'Giriş yasağı bulunmasına rağmen sınırdan kaçak/izinsiz girmeye teşebbüs eden yabancılara uygulanan ceza kaydıdır. Giriş verilmez, INAD uygulanır.', N'İdari para cezası tahsil edilir, çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-96', N'Tanınan Sürede Ülkemizden Çıkış Yapmamanın İdari Para Cezası (YUKK m. 56 Terke Davet İhlali)', NULL, 1, N'Yabancı sınır kapısına geldiğinde, ödenmemiş terke davet ihlali para cezasını vezneye defaten öderse sınır personeli tarafından N-96 kaldırılarak girişi sağlanır. Ödemezse İNAD işlemi uygulanır.', N'Terke davet süresinde çıkış yapmadığı tespit edilen yabancı hakkında sınır personeli tarafından N-96 kodlu idari para cezası tahakkuk ettirilir; ödemezse borçlu çıkışı yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-97', N'Adres Değişikliğini Bildirmeme / Gerçeğe Aykırı Beyan İdari Para Cezası (5490 Sayılı Kanun m. 50/68)', NULL, 1, N'Adres beyanı idari para cezasını sınır kapısında öderse N-97 kodu sınır kapısı personeli tarafından resen kaldırılarak ülkeye girişi sağlanır. Ödemezse İNAD uygulanır.', N'Adres ihlali para cezası tebliğ ve tahsil edilir; ödenmemesi durumunda borçlu olarak çıkışına izin verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-119', N'6735 Sayılı Kanuna Göre İzinsiz Çalışmanın İdari Para Cezası (Kaçak Çalışma Cezası)', NULL, 1, N'6735 sayılı Uluslararası İşgücü Kanunu kapsamında izinsiz çalışmaktan doğan para cezasını sınır kapısında öderse N-119 kaldırılarak ülkeye girişi sağlanır. Ödemezse İNAD edilerek geri çevrilir.', N'İzinsiz çalışma idari yaptırım kararı kontrol edilir; tahsilat yapılır veya N-119 borcu sistemde aktif bırakılarak çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-120', N'Vize/İkamet İhlali Para Cezasını Ödemeden Çıkan Yabancılar Tahdidi (Genelge 2024/5 m. 6 & 12)', NULL, 1, N'Ödenmemiş vize ihlal cezası ve defter bedeli vezneye yatırılmadan ve varsa Ç-kodu giriş yasağı süresi dolmadan Türkiye''ye girişine kesinlikle izin verilmez.', N'Para cezası tahsil edilerek çıkışı sağlanır; ödemezse N-120 tahdidi aktif tutulur.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-135', N'Yasadışı Giriş-Çıkış Yapmanın veya Teşebbüs Etmenin İdari Para Cezası (6458 Sayılı Kanun m. 5, 102)', NULL, 1, N'Yasadışı giriş-çıkış idari para cezasını öderse ve başkaca engeli (Ç-113 süresi vb.) yoksa N-135 kaldırılarak girişi sağlanır. Para cezasını ödemezse İNAD işlemi yapılır.', N'Yasadışı giriş-çıkış fiilinden kaynaklanan idari para cezası tahsil edilir; ödenmemesi halinde sınır personeli tarafından N-135 kodu girilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-136', N'Sınır Dışı Seyahat Masrafları Borcu (Kamu Tarafından Karşılanan İntikal/Uçak Masrafı)', NULL, 1, N'Daha önce kamu bütçesinden karşılanan sınır dışı seyahat masraflarını hudut veznesine eksiksiz ödemesi halinde N-136 kaldırılarak girişi sağlanır. Ödemeyi reddederse İNAD edilir.', N'Yabancının sınır dışı seyahat borcu tahakkuku kontrol edilir; tahsilat makbuzu düzenlenir veya borç şerhiyle çıkışı yaptırılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-168', N'6458 Sayılı Kanunun 102 nci Maddesinin Ç Bendine Muhalefet İdari Para Cezası (İşlemler Sırasında Kaçanlar)', NULL, 1, N'Geri gönderme veya sevk işlemleri sırasında kaçmaktan kaynaklı idari para cezasını öderse N-168 kaldırılarak girişi sağlanır; aksi halde İNAD uygulanır.', N'Kaçma eylemine istinaden idari para cezası tahakkuk ettirilerek çıkışı yaptırılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-169', N'Bakanlıkça Belirlenen İdari Yükümlülüklere Uymamaya İlişkin İdari Para Cezası (YUKK m. 102/6)', NULL, 1, N'İçişleri Bakanlığı düzenlemelerindeki yükümlülüklere uymama cezasını öderse N-169 kaldırılarak ülkeye girişi sağlanır; ödemezse İNAD işlemi uygulanır.', N'İdari para cezası tahakkuku kontrol edilir ve çıkış işlemi gerçekleştirilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-170', N'Kabahatler Kanunu ve Kamu Alacağı Kaynaklı İdari Para Cezası', NULL, 1, N'Borç ödenmedikçe giriş verilmez.', N'Vezne tahsilatı yapılır, çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-171', N'Belirlenen Yasal Yükümlülükleri Yerine Getirmemeden Kaynaklanan İdari Para Cezası (YUKK m. 102/1-e)', NULL, 1, N'YUKK 102/1-e kapsamındaki idari para cezasını öderse N-171 kaldırılarak ülkeye girişi sağlanır; ödemezse İNAD edilir.', N'Para cezası tahakkuku kontrol edilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-172', N'Ulusal Destekli Gönüllü Geri Dönüşten Vazgeçen / Firar Edenlerin Seyahat Masrafı Borcu', NULL, 1, N'Geri dönüş sürecinde yapılan devlet harcama masraflarını ödemesi halinde N-172 kaldırılarak girişine izin verilir; ödemezse İNAD uygulanır.', N'Masraf tahsilat durumu kontrol edilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-186', N'Geri Gönderme Merkezlerinde (GGM) Disiplin Kurallarına Uymamaya İlişkin İdari Para Cezası', NULL, 1, N'GGM disiplin cezası borcunu hudutta ödemesi halinde N-186 kaldırılarak girişi sağlanır; ödemezse İNAD uygulanır.', N'Disiplin cezası tebliği ve tahsilatı kontrol edilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-187', N'Yeniden Yerleştirmeyi Reddeden veya Semti Meçhule Giden Yabancılar İçin İdari Para Cezası (YUKK m. 102/6)', NULL, 1, N'Yeniden yerleştirmeyi reddetme para cezasını öderse N-187 kaldırılarak girişi sağlanır; aksi halde İNAD uygulanır.', N'Para cezası tahsilatı yapılarak çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'O-100', N'Ülkeye Girişi 1 Yıl Yasaklı Yabancı', 12, 1, N'MADDE 15- (I) 0-100 (Ülkeye Girişi I yıl Yasaklı Yabancı) kodlu veri girişi;
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'O-176', N'Uluslararası Koruma Başvurusu Geri Çekilmiş Sayılan veya Statüsü Sona Eren/Erdirilen Yabancılar (3 Yıl Giriş Yasağı)', 36, 1, N'3 YIL SÜREYLE ÜLKEYE GİRİŞİ YASAKTIR. Dış temsilciliklerden Başkanlık onaylı Özel Meşruhatlı Vize almadığı sürece ülkeye girişine izin verilmez; İNAD (Kabul Edilemeyen Yolcu) işlemi uygulanır.', N'Çıkışına engel durum yoktur; genel vize ve pasaport kontrolleri yapılarak çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'O-177', N'Uluslararası Koruma Başvurusu Reddedilen, Kabul Edilemez Bulunan, Muhtaç Değil veya Statüsü İptal Edilenler (5 Yıl Giriş Yasağı)', 60, 1, N'5 YIL SÜREYLE ÜLKEYE GİRİŞİ YASAKTIR. Dış temsilciliklerimizden Başkanlığa istizan edilerek verilmiş Özel Meşruhatlı Vize hamili olmadığı sürece kesinlikle girişine izin verilmez, İNAD işlemi uygulanarak geri çevrilir.', N'Çıkışına engel durum yoktur; genel hükümlere göre çıkışı yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'G', N'Kamu Düzeni, Kamu Güvenliği veya Kamu Sağlığı Açısından Girişi Yasaklanan Yabancılar (Genel G Tahdidi)', NULL, 1, N'Kamu düzeni veya güvenliği açısından ülkeye girmesi sakıncalı yabancıdır. Kesinlikle ülkeye girişine izin verilmez, İNAD işlemi yapılarak geldiği ülkeye geri gönderilir. Yalnızca Başkanlık yazılı talimatı veya Türk vatandaşı tespiti halinde kaldırılabilir.', N'Çıkışına mani adli bir yakalama veya arama kaydı yoksa ülkeden çıkışına izin verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'ÇÇ-101', N'Çift Tahditli / İnceleme Kaydı Bulunan Yabancılar (Hudut Kapısı Detaylı Tahkikat)', NULL, 1, N'Yolcu ikinci hat (Detaylı Kontrol Odası) personeline teslim edilir. Sistemdeki tüm aktif tahdit kayıtları ve vize/ihlal durumları ayrı ayrı incelenir; yetkili amir onayı olmadan giriş işlemi yapılmaz.', N'Çıkış yapmasında adli bir engel, mahkeme tedbiri veya ödenmemiş harç/ceza borcu olup olmadığı kontrol edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Marine Tecnician', N'Gemi Bakım-Onarım Teknik Personeli Giriş/Çıkış Prosedürü (Gemiadamı Yeterlilik Belgesi)', NULL, 1, N'Gemiadamı Cüzdanı, teknik personel görevlendirme yazısı, gemi acentesi taahhütnamesi ve Liman Başkanlığı uygunluk yazısı kontrol edilir; genel vize/muafiyet rejimine göre geçici girişine izin verilir.', N'Görevli olduğu gemiye intikali veya havayoluyla acente refakatinde transit çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Çıkış İptali', N'Hudut Kapılarında Yürütülen Çıkış İptal İşlemleri (Uçağa Binemeyen / Seferi İptal Olan Yolcular)', NULL, 1, N'Giriş kapısında uygulanmaz.', N'Çıkış damgası tatbik edildikten sonra uçuş iptali, hastalık veya teknik nedenle uçağa binemeyen yolcuların pasaportundaki çıkış kaşesi kırmızı kalemle çift çizgi çekilerek ''İPTAL'' kaşesi basılır, sistemden çıkış kaydı düşülür ve pasaportu teslim edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Mürettebat', N'Yabancı Hava Yolu ve Gemi Mürettebatının Hudut Kapılarından Giriş/Çıkış Kontrolü', NULL, 1, N'ICAO GenDec (General Declaration) manifestosu ve geçerli Mürettebat Kimlik Kartı (CMC / Gemiadamı Cüzdanı) kontrol edilir; uçuş/sefer ekibi vizeden muaftır.', N'GenDec listesi ile karşılaştırılarak mürettebatın uçağa/gemiye binişi ve çıkış işlemi tamamlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'pasaport-iptali', N'Hudut Kapılarında Pasaport Fiziki İptal İşlemleri (Zayi, Sahte, Deforme, Hükümsüz Belgeler)', NULL, 1, N'Sahte, tahrif edilmiş veya hükümsüz seyahat belgesi tutanakla zapt edilir; belgenin sağ üst köşesi kesilerek/delinerek fiziki iptal işlemi uygulanır, yolcu İNAD edilir ve adli tahkikat başlatılır.', N'İptal edilmiş veya sahte belgeyle çıkış yapılamaz; yabancı konsolosluğundan geçici seyahat belgesi temin edilene kadar çıkış verilmez.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Çalışma-izni', N'Çalışma İzni ve Çalışma İzni Uzatma Müracaat Belgesi İle Hudut Kapılarından Giriş/Çıkışlar', NULL, 1, N'Çalışma ve Sosyal Güvenlik Bakanlığı izin belgesi veya barkodlu geçerli ''Çalışma İzni Uzatma Müracaat Belgesi'' ve harç makbuzu ibraz edenlerin vize süresi aranmaksızın ülkeye girişine izin verilir.', N'Çalışma izninin geçerlilik tarihi ve ihlal durumu kontrol edilir; iptal edilmişse V-88 ve para cezası hükümleri uygulanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'S-TİPİ-VİZE', N'S Tipi E-Vize Uygulamasının 15 Temmuz 2021 Tarihinde Sonlandırılmasına İlişkin Talimat', NULL, 1, N'15 Temmuz 2021 itibariyle S Tipi E-Vize uygulaması yürürlükten kalkmıştır. Bu vize türüyle gelen yolcuların belgeleri geçersiz sayılır; genel vize/muafiyet şartlarını taşımıyorsa İNAD işlemi yapılarak geri gönderilir.', N'Genel vize ve kalış ihlali kontrolleri yapılarak çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'3.Ülkelere-Çıkış', N'Ülkemizden Üçüncü Ülkelere Çıkışlarda Belge Kontrolü (İçişleri Bakanlığı Genelge No: 2021-2)', NULL, 1, N'Girişte uygulanmaz.', N'Türkiye üzerinden üçüncü ülkeye gidecek yolcuların hedef ülkeye ait geçerli vize, oturum kartı veya pasaportu havayolu ve pasaport polisi tarafından titizlikle denetlenir. Sahte belge veya vizesiz yolcuların uçağa binişine izin verilmez.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-95', N'Giriş Yasağı İhlalinin İdari Para Cezası Tahdidi', NULL, 1, N'Giriş yasağı bulunmasına rağmen sınırdan kaçak/izinsiz girmeye teşebbüs eden yabancılara uygulanan ceza kaydıdır. Giriş verilmez, INAD uygulanır.', N'İdari para cezası tahsil edilir, çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N TAHDİT KODLARI', N'(N) Ön İzin ve İdari Para Cezaları Tahdit Kodları Genel Uygulama Rehberi (Genelge 2024/4)', NULL, 1, N'N kodları giriş yasağı olmayıp ön izin ve kamu alacağı bildirimidir. İdari para cezası kaynaklı olanlarda (N-95, N-96, N-120 vb.) ceza hudutta defaten ödendiğinde sınır personeli tarafından resen kaldırılarak girişe izin verilir.', N'N kodu çıkış engeli oluşturmaz. Yolcunun cezalı harç ve idari para cezası tahakkuku kontrol edilir; ödemezse borçlu olarak çıkışı yaptırılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'İnterpol Tahdit Kayıtları', N'İnterpol Tahdit ve Veri Tabanı Kayıtları Genel Uygulama Esasları', NULL, 1, N'Pasaport kontrolünde İnterpol şerhi çıkan şahıslarda bülten türü (Kırmızı, Mavi, Sarı, Yeşil, Difüzyon) tespit edilir; derhal İnterpol Dairesi ve ilgili şube aranarak verilecek adli talimata göre hareket edilir.', N'Yurt dışına çıkışı yasaklanan veya uluslararası yakalama kararı olan şahıslar gözaltına alınır; savcılığa teslim edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'İnterpol  Birleştirilmiş Genelge', N'Emniyet Genel Müdürlüğü İnterpol-Europol Birleştirilmiş Uygulama Genelgesi', NULL, 1, N'Uluslararası aranan, iadesi talep edilen veya difüzyon mesajı bulunan şahısların hudut kapılarında tespiti halinde nöbetçi savcı ve İnterpol Daire Başkanlığı talimatları doğrultusunda adli işlem yapılır.', N'Aranan şahısların kaçmasını önlemek üzere sistem uyarıları titizlikle işletilir; adli makamlarla irtibata geçilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'KIRMIZI BULTEN TAMIM', N'Interpol Kırmızı Bülten ve Uluslararası Düzeyde Suçlu İadesi Uygulama Tamimi', NULL, 1, N'Kırmızı bülten ile uluslararası düzeyde aranan yabancı tespit edildiğinde derhal nöbetçi Cumhuriyet Savcısına bilgi verilir; şahıs muhafaza altına alınarak adli makamlara teslim edilir. Ülkeye girişine asla izin verilmez.', N'Hakkında Kırmızı Bülten bulunan şahsın yurt dışına kaçışı engellenir; derhal yakalama müzekkeresi düzenlenerek adli makamlara sevk edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N' (S) KODU İLE SAHTE KİMLİK', N'Sahte Pasaport, Vize veya Kimlik Belgesi Kullanımına İlişkin Tahdit', NULL, 1, N'Sahte belge kullanma şüphesidir. Yolcu Belge İnceleme Uzmanına (BİU) yönlendirilir. Sahtecilik tespit edilirse adli tahkikat başlatılır, şahıs gözaltına alınır.', N'Belge incelenir, sahtecilik varsa Nöbetçi Savcılığa teslim edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ş (İnterpol Şube) Kodu', N'Sarı Bülten (Kayıp Şahıs) Tahdidi', NULL, 1, N'1-) Tahdit kaydı çıktısı alınır.
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'B – YEŞİL BÜLTEN (Y) KODU', N'Interpol Yeşil Bülten (Uluslararası Sabıkalı / Suç Kaydı Bulunan Şahıslar İstihbari Takip)', NULL, 1, N'Uluslararası suç kaydı bulunan şahıs ikinci hat kontrolüne alınır; seyahat amacı, kalacağı yer ve maddi imkanları incelenir. Kamu güvenliği açısından sakıncalı görülürse İNAD edilir; sakınca yoksa girişi sağlanır ve istihbarat birimlerine bilgi verilir.', N'Çıkışında adli yakalama veya seyahat kısıtlaması yoksa genel hükümlere göre çıkışı yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'MAVİ BÜLTEN (M) KODU', N'Interpol Mavi Bülten (Kimlik Tespiti ve İstihbari Takip)', NULL, 1, N'Kimlik tespiti, seyahat amacı, kalacağı yer ve irtibat bilgileri tutanağa bağlanır. Interpol Daire Başkanlığına bildirilir; adli yakalama yoksa girişi sağlanır.', N'Seyahat güzergâhı tutanağa bağlanarak Interpol Dairesine bilgi verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N' KIRMIZI BÜLTEN (H) KODU', N'Interpol Kırmızı Bülten İle Uluslararası Düzeyde Aranan Şahıslar', NULL, 1, N'DERHAL YAKALAMA YAPILIR! Şahıs enterne edilir, pasaport kontrol kabininden çıkarılmaz. Nöbetçi Cumhuriyet Savcısı, Interpol Daire Başkanlığı ve ilgili kolluk birimine derhal bilgi verilir. İade evrakı gelene kadar nezarette tutulur.', N'DERHAL YAKALAMA YAPILIR! Şahsın çıkışına kesinlikle izin verilmez, enterne edilerek Nöbetçi Savcılığa ve Interpol Şubeye teslim edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N' (A) KODU İLE MAHKEME KARARI', N'Mahkeme Kararı İle Konulan Adli Tedbir / Giriş-Çıkış Şerhi', NULL, 1, N'Mahkemece konulmuş giriş yasağı veya tedbir kararı sorgulanır. Karar doğrultusunda işlem yapılır.', N'DİKKAT: UYAP/POLNET üzerinden mahkemece verilmiş yurt dışına çıkış yasağı (CMK 109/3-a) olup olmadığı kontrol edilir. Çıkış yasağı varsa şahıs derhal gözaltına alınarak adli makamlara teslim edilir, çıkış verilmez.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'(B) KODU İLE MALİYE TAHDİTİ', N'Maliye Bakanlığı / Amme Alacakları Yurt Dışı Çıkış Tahdidi', NULL, 1, N'Maliye Bakanlığı amme alacağı kaydı kontrol edilir.', N'Mahkeme kararına dayalı vergi/maliye çıkış yasağı olup olmadığı kontrol edilir; adli çıkış yasağı yoksa çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'(D) KODU İLE BAKANLIK TAHDİTİ', N'İçişleri Bakanlığı Genel Güvenlik ve İdari İnceleme Tahdidi', NULL, 1, N'İçişleri Bakanlığı şerhi kontrol edilir. Bakanlık izni olmaksızın yurda giriş verilemez.', N'Bakanlık talimatı incelenir, engel karar yoksa çıkışı yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'J KODU YAKLAMA TAHDİDİ  GİRİŞ', N'Adli Arama ve Yakalama Müzekkeresi Bulunan Şahıslar (Giriş)', NULL, 1, N'YAKALAMA YAPILIR. UYAP yakalama emri gereğince nöbetçi savcılık talimatı doğrultusunda derhal gözaltı işlemi yapılır.', N'YAKALAMA YAPILIR. Adli makamlara teslim edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'J KODU YAKLAMA TAHDİDİ  ÇIKIŞ', N'Adli Arama ve Yakalama Müzekkeresi Bulunan Şahıslar (Çıkış)', NULL, 1, N'YAKALAMA YAPILIR. Adli makamlara teslim edilir.', N'YAKALAMA YAPILIR. Çıkışına izin verilmez, savcılık talimatıyla adli makamlara teslim edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'G (Bakanlık) Kodu GİRİŞ', N'İçişleri Bakanlığı Genel Güvenlik ve Kamu Düzeni Tahdidi (GİRİŞ YASAĞI)', NULL, 1, N'Kamu düzeni ve genel güvenlik açısından İçişleri Bakanlığı tarafından konulan giriş yasağıdır. Kesinlikle ülkeye girişine izin verilmez, derhal İNAD işlemi uygulanarak geri çevrilir. Yalnızca Bakanlık yazılı onayı ile kaldırılabilir.', N'Çıkışına mani adli bir karar yoksa genel hükümlere göre çıkışı yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'K (İl KOM Şube) Kodu GİRİŞ', N'Kaçakçılık ve Organize Suçlarla Mücadele Şube Yakalama Şerhi', NULL, 1, N'Kaçakçılık ve Organize Suçlarla Mücadele yakalama şerhidir. Şahıs enterne edilerek derhal KOM Şube görevlilerine teslim edilir.', N'KOM Şube talimatı gereği yakalama yapılır, çıkış verilmez.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'M (İnterpol Şube) Kodu', N'Mavi Bülten Tahdidi', NULL, 1, N'1-) Tahdit kaydı çıktısı alınır.
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'R-65 (İl Asayiş Şube) Kodu', N'Kayıp Şahıs Tahdidi', NULL, 1, N'1-) Tahdit kaydı çıktısı alınır.
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Y (İnterpol Şube) Kodu', N'Mavi Bülten Tahdidi', NULL, 1, N'1-) Tahdit kaydı çıktısı alınır.
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-75 –V-77(ahıska türkü olmadığı anlaşılan)İkamet Tahdidi', N'V-75 –V-77(ahıska türkü olmadığı anlaşılan)İkamet Tahdidi', NULL, 1, N'1-) Tahdit kaydı çıktısı alınır.
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'ZAYİ PASAPORT', N'Zayi / Kayıp Pasaport Bildirimleri ve Tahdit İle İlgili Sınır İşlemleri', NULL, 1, N'Zayi veya kayıp kaydı bulunan pasaport ile gelen şahsın belgesine el konulur; kimlik hırsızlığı ve sahtecilik tahkikatı yapılır. Geçerli seyahat belgesi ibraz edemezse kabul edilemez yolcu (İNAD) işlemi uygulanır.', N'Ülkemizde pasaportunu kaybeden yabancının temsilciliğinden aldığı ''Geçici Pasaport / Laissez-Passer'' ve İl Emniyet / Göç İdaresi kayıp belgesi kontrol edilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-119', N'Vize İhlali Para Cezasını Ödemeden Çıkan Yabancılar (Genelge 2024/5)', 12, 1, N'1 yıl süreyle giriş verilmez. Süre dolduktan sonra gelişinde ödenmemiş para cezası tahsil edilmeden giriş yaptırılmaz.', N'İhlal para cezası tahsil edilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-120', N'Vize/İkamet İhlali Para Cezasını Ödemeyen Yabancılar (Genelge 2024/5 m. 6/1/a)', 3, 1, N'3 aylık yasak süresi dolmadan ve ödenmemiş ceza ödenmeden giriş verilmez. INAD işlemi uygulanır.', N'Varsa yeni ihlal cezası tahsil edilerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-135', N'YUKK m. 102 Kapsamında İdari Para Cezasından Kaynaklı Giriş Yasağı', 60, 1, N'5 yıl boyunca ülkeye girişi yasaktır, INAD uygulanır. Ceza ödense dahi yasak süresi bitmeden girilemez.', N'İdari para cezaları tahsil edilir, çıkışı yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-136', N'Seyahat ve Sınır Dışı Masraflarını Karşılamayan Yabancılar (YUKK m. 54)', NULL, 1, N'Devlet tarafından karşılanan sınır dışı ve seyahat masrafları Hazine veznesine ödenmedikçe ve Göç İdaresi tahdidi kaldırmadıkça giriş verilmez.', N'Çıkışına engel teşkil etmez.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-137', N'Terke Davet Edildiği Halde Süresinde Çıkış Yapmayan Yabancılar (5 Yıl Yasak)', 60, 1, N'5 yıl boyunca ülkeye girişi yasaktır, INAD uygulanır.', N'20.605 TL İdari Para Cezası ve vize ihlal cezaları tahakkuk ettirilir. Tahkikat tutanağı düzenlenerek çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-138', N'İnatçı Giriş İhlali / Mükerrer Kabul Edilmeyen Yolcu (INAD) Şerhi', 60, 1, N'Doğrudan INAD işlemi uygulanarak muhafaza altına alınır ve ilk vasıtayla geri gönderilir.', N'Adli mani yoksa çıkışı verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'Ç-167', N'3 Ay - 6 Ay Arası Vize İhlali Yapanlar (1 Ay Giriş Yasağı - Genelge 2024/5 m. 6)', 1, 1, N'1 aylık yasak süresi dolmadan giriş verilemez. Süre dolduktan sonra genel vize rejimine göre giriş yapabilir.', N'Varsa yeni ihlal hesaplanır ve tahsil edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'V-77', N'Ahıska Türkü Olmadığı Halde Soydaş Başvurusunda Bulunanlar', NULL, 1, N'Ahıska Türkü soydaş muafiyetlerinden yararlanamaz. Vize rejimine tabi tutulur.', N'Çıkışı sağlanır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'N-99', N'Ödenmemiş İdari Para Cezası Tahdidi (YUKK veya Kabahatler Kanunu)', NULL, 1, N'Hudut veznesine para cezası ödenmeden girişine müsaade edilmez. Ceza ödendikten sonra vize rejimi kurallarına göre girişi sağlanır.', N'Vezneden tahsilat yapılır, çıkış mührü tatbik edilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'G-82', N'Milli Güvenlik Açısından Ülkeye Girişi İzne Tabi Yabancılar (Genelge 2024/4 Madde 14)', NULL, 1, N'KESİNLİKLE YURDA GİRİŞ VERİLEMEZ. İstizan veya Bakanlık yazılı izni olmaksızın giriş müsaadesi verilmez. Derhal TEM ve İstihbarat Şube Müdürlüklerine bilgi verilerek Kabul Edilmeyen Yolcu (INAD) tebligatı yapılır ve ilk vasıtayla mahrecine geri gönderilir.', N'Hakkında adli arama kaydı veya tahkikat kararı olup olmadığı TEM/İstihbarat birimleriyle teyit edilir, talimat doğrultusunda işlem yapılır.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'G-87', N'Genel Güvenlik Açısından Sakıncalı Görülen Yabancılar', NULL, 1, N'Ülkeye girişi sakıncalıdır, derhal INAD kapsamına alınarak geri çevrilir.', N'Kolluk birimleri koordinesinde çıkışı verilir.');
    INSERT INTO #FullTahditData (Kod, Aciklama, SureAy, Aktif, GirisGelirse, CikisGelirse) VALUES (N'B - YEŞİL BÜLTEN (Y) KODU', N'Interpol Yeşil Bülten (Uluslararası Sabıkalı Şahıs Takibi)', NULL, 1, N'Sabıkalı/istihbari kaydı olan şahıstır. Gümrük muhafaza ile koordineli detaylı arama ve mülakat yapılır. Suç unsuru yoksa girişi sağlanır.', N'Bilgi amaçlı kontrol yapılır, çıkışı verilir.');
